wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::{http_client, notifier};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => out.push(b as char),
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment record, fetched on every call per the graph author's
        // extended grant. Failure is tolerated and the result does not
        // influence the output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&composed.overview)
        );
        let _ = http_client::fetch(&url);

        let message = format!(
            "Digest {}: {}\n{} entries, {} items considered",
            composed.date,
            composed.overview,
            composed.entries.len(),
            composed.considered.len()
        );
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
